const source = $input.first().json || {};
const payload = source.body || source;
const message = payload.message || {};
const text = message.text || payload.text || payload.user_message || payload.message_text || '';
const chat = message.chat || {};
const from = message.from || {};
return [{ json: {
  chat_id: chat.id || payload.chat_id || payload.chatId || '',
  message_id: message.message_id || payload.message_id || payload.messageId || '',
  user_message: text,
  telegram_username: from.username || payload.telegram_username || payload.username || '',
  received_at: new Date().toISOString()
}}];

const codeFence = '```';
const source = $input.first().json;
let raw = source.output || source.text || source.response || '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim();
if (raw.startsWith(codeFence)) raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first >= 0 && last > first) raw = raw.slice(first, last + 1);
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = {
    reply_to_user: 'I can help with AI lead qualification, RAG chatbots, and approval workflows. Please send your name, email, and what you want to automate.',
    user_registered: false,
    lead_data: { name: '', email: '', use_case: '', budget: '', timeline: '', intent_level: '' },
    lead_score: 0,
    qualified: false,
    reason: error.message,
    conversation_summary: ''
  };
}
const sourceMessage = $('Normalize Telegram Message').first().json;
const lead = parsed.lead_data || {};
let reply = String(parsed.reply_to_user || '').trim();
if (!reply) reply = 'I can help with AI automation and lead qualification. What would you like to automate?';
if (reply.length > 900) reply = `${reply.slice(0, 860).trim()}...

What is the most important outcome you want from this automation?`;
const sourceText = String(sourceMessage.user_message || '').toLowerCase();
const hasBudget = Boolean(String(lead.budget || '').trim());
const explicitNoBudget = /budget\s+(is\s+)?(not\s+)?(confirmed|set|ready)|no\s+budget|budget\s+unknown|not\s+sure\s+.*budget/.test(sourceText);
const explicitStartIntent = /(ready\s+to\s+start|go\s+ahead|book\s+a\s+call|approve|decision|start\s+this|kick\s+off)/.test(sourceText);
let normalizedScore = Math.max(0, Math.min(100, Number(parsed.lead_score || 0)));
let normalizedQualified = Boolean(parsed.qualified) && normalizedScore >= 70;
if ((!hasBudget || explicitNoBudget) && !explicitStartIntent) {
  normalizedScore = Math.min(normalizedScore, 65);
  normalizedQualified = false;
}
return [{ json: {
  ...sourceMessage,
  reply_to_user: reply,
  user_registered: Boolean(parsed.user_registered),
  Name: lead.name || '',
  Email: lead.email || '',
  use_case: lead.use_case || '',
  budget: lead.budget || '',
  timeline: lead.timeline || '',
  intent_level: lead.intent_level || '',
  lead_score: normalizedScore,
  qualified: normalizedQualified,
  reason: parsed.reason || '',
  conversation_summary: parsed.conversation_summary || ''
}}];

